INSERT INTO `chapters` VALUES
(1, 1, 'Mecanique du Point et du Solide', 'mecanique-point-solide', 'Cinematique, dynamique newtonienne, energetique et oscillateurs mecaniques.', NULL, 'l1', 1, 1, '2026-08-13 21:23:45'),
(2, 1, 'Thermodynamique Statistique & Macroscopique', 'thermodynamique', 'Principes de la thermodynamique, machines thermiques et entropie.', NULL, 'l2', 2, 2, '2026-08-13 21:23:45'),
